SECTION "HH sound VBlank glue", ROM0[$0B9F]

; HH_SndVBlank: the game's sound entry, jumped to at the end of the VBlank handler (ROM0 $00CC).
; Passes the game's requests (hSfxReq with a priority test, hMusReq) to the driver and runs it in bank 1.
HH_SndVBlank:
    ldh a,[hTimerVec+1]             ; 0b9f f0 f6     no sound update while a PCM sample plays
    or a                            ; 0ba1 b7      
    ret nz                          ; 0ba2 c0      
    ld a,[wSndBusy]                 ; 0ba3 fa ff df  re-entry guard
    or a                            ; 0ba6 b7      
    ret nz                          ; 0ba7 c0      
    ld a,$ff                        ; 0ba8 3e ff   
    ld [wSndBusy],a                 ; 0baa ea ff df
    ldh a,[hSfxReq]                 ; 0bad f0 d1     SFX request from the game
    or a                            ; 0baf b7      
    jr z,HH_SndVBlank.music         ; 0bb0 28 17   
    ld hl,HH_SfxPriority            ; 0bb2 21 05 0c  hl = HH_SfxPriority + id (rst $08: hl += a)
    rst $08                         ; 0bb5 cf      
    ld a,[wSfxReq]                  ; 0bb6 fa 0f de  an SFX already requested/playing?
    or a                            ; 0bb9 b7      
    jr z,HH_SndVBlank.takeSfx       ; 0bba 28 05   
    ldh a,[hSfxPrio]                ; 0bbc f0 d2     yes: refused if the new value is higher (lower value = more important)
    cp [hl]                         ; 0bbe be      
    jr c,HH_SndVBlank.music         ; 0bbf 38 08   
.takeSfx
    ld a,[hl]                       ; 0bc1 7e        hSfxPrio = priority of the new SFX
    ldh [hSfxPrio],a                ; 0bc2 e0 d2   
    ldh a,[hSfxReq]                 ; 0bc4 f0 d1   
    ld [wSfxReq],a                  ; 0bc6 ea 0f de  pass the id to the driver
.music
    ldh a,[hMusReq]                 ; 0bc9 f0 d3     music request: passed on without a test
    or a                            ; 0bcb b7      
    jr z,HH_SndVBlank.clear         ; 0bcc 28 03   
    ld [wMusReq],a                  ; 0bce ea 1f de
.clear
    xor a                           ; 0bd1 af        both requests consumed
    ldh [hSfxReq],a                 ; 0bd2 e0 d1   
    ldh [hMusReq],a                 ; 0bd4 e0 d3   
    ld a,$01                        ; 0bd6 3e 01     bank 1
    ldh [hROMBank],a                ; 0bd8 e0 8a   
    ld [$2100],a                    ; 0bda ea 00 21
    ld a,[wMusReq]                  ; 0bdd fa 1f de  hCurMusic = the music id (not 0 or $FF)
    or a                            ; 0be0 b7      
    jr z,HH_SndVBlank.curMusic      ; 0be1 28 06   
    cp $ff                          ; 0be3 fe ff   
    jr z,HH_SndVBlank.curMusic      ; 0be5 28 02   
    ldh [hCurMusic],a               ; 0be7 e0 d4   
.curMusic
    ld a,[wSlowMo]                  ; 0be9 fa fd df  slow motion: wait 4096 loop iterations before the update
    or a                            ; 0bec b7      
    jr z,HH_SndVBlank.update        ; 0bed 28 0e   
    ld a,[wSlowMoOn]                ; 0bef fa fe df
    or a                            ; 0bf2 b7      
    jr z,HH_SndVBlank.update        ; 0bf3 28 08   
    ld hl,$1000                     ; 0bf5 21 00 10
.slowLoop
    dec hl                          ; 0bf8 2b      
    ld a,l                          ; 0bf9 7d      
    or h                            ; 0bfa b4      
    jr nz,HH_SndVBlank.slowLoop     ; 0bfb 20 fb   
.update
    call HH_SndUpdateJP             ; 0bfd cd 00 40  the driver
    xor a                           ; 0c00 af      
    ld [wSndBusy],a                 ; 0c01 ea ff df
    ret                             ; 0c04 c9      

; HH_SfxPriority: one byte per id (81 bytes; ids $45-$50 are padding).
; A new SFX is refused while the current one has a higher priority; $FE/$FF = music-only ids.
HH_SfxPriority:
    db $ff, $00, $fe, $fe, $fe, $fe, $fe, $fe, $fe, $fe, $fe, $fe, $fe, $fe, $fe, $fe; 0c05
    db $fe, $fe, $0d, $40, $40, $03, $10, $08, $09, $0a, $0d, $0d, $0c, $0b, $09, $02; 0c15
    db $01, $4a, $0f, $4c, $50, $10, $70, $0c, $58, $0d, $60, $20, $0f, $09, $38, $49; 0c25
    db $20, $0d, $18, $38, $19, $70, $0d, $20, $20, $0d, $0b, $70, $20, $0c, $0b, $10; 0c35
    db $48, $70, $70, $0d, $70, $fe, $fe, $fe, $fe, $fe, $fe, $fe, $fe, $fe, $fe, $fe; 0c45
    db $80                          ; 0c55

SECTION "HH PCM player", ROM0[$2350]

; HH_ScriptPlayPCM: opcode $1A of the game's script interpreter (table $221F, ROM0 $2344).
; de = script pointer. Decodes the bitstream into NR50 bytes at $C300, silences the driver, then plays.
HH_ScriptPlayPCM:
    ld hl,hPCMCount                 ; 2350 21 8e ff  script opcode $1A: count (negative word), then the bitstream
    ld a,[de]                       ; 2353 1a      
    inc de                          ; 2354 13      
    ld [hl+],a                      ; 2355 22      
    ld a,[de]                       ; 2356 1a      
    inc de                          ; 2357 13      
    ld [hl+],a                      ; 2358 22      
    xor a                           ; 2359 af      
    ld [hl+],a                      ; 235a 22      
    ld [hl+],a                      ; 235b 22      
    ld [hl],a                       ; 235c 77      
    ld c,$01                        ; 235d 0e 01     c = 1: read a byte on the first bit
    ld hl,$c300                     ; 235f 21 00 c3  samples go to WRAM $C300 up
.decode
    push hl                         ; 2362 e5      
    call HH_PCMDecode               ; 2363 cd 1a 26
    ld l,a                          ; 2366 6f        nibble v -> NR50 byte v*$11
    swap a                          ; 2367 cb 37   
    or l                            ; 2369 b5      
    pop hl                          ; 236a e1      
    ld [hl+],a                      ; 236b 22      
    ldh a,[hPCMCount]               ; 236c f0 8e   
    inc a                           ; 236e 3c      
    ldh [hPCMCount],a               ; 236f e0 8e   
    jr nz,HH_ScriptPlayPCM.decode   ; 2371 20 ef   
    ldh a,[hPCMCount+1]             ; 2373 f0 8f   
    inc a                           ; 2375 3c      
    ldh [hPCMCount+1],a             ; 2376 e0 8f   
    jr nz,HH_ScriptPlayPCM.decode   ; 2378 20 e8   
    ld [hl],$ff                     ; 237a 36 ff     $FF terminator
    ld a,$01                        ; 237c 3e 01     SFX 1 and music 1: silence everything
    ldh [hSfxReq],a                 ; 237e e0 d1   
    ldh [hMusReq],a                 ; 2380 e0 d3   
.waitSilence
    ldh a,[hMusReq]                 ; 2382 f0 d3     wait until the driver took both and music 1 ended
    or a                            ; 2384 b7      
    jr nz,HH_ScriptPlayPCM.waitSilence; 2385 20 fb   
    ld a,[wMusReq]                  ; 2387 fa 1f de
    or a                            ; 238a b7      
    jr nz,HH_ScriptPlayPCM.waitSilence; 238b 20 f5   
    ld a,$00                        ; 238d 3e 00     hPCMPtr = $C300
HH_PCMStart:
    ldh [hPCMPtr],a                 ; 238f e0 d6   
    ld a,$c3                        ; 2391 3e c3   
    ldh [hPCMPtr+1],a               ; 2393 e0 d7   
    ld a,LOW(HH_PCMTimerISR)        ; 2395 3e e7     timer vector = HH_PCMTimerISR
    ldh [hTimerVec],a               ; 2397 e0 f5   
    ld a,HIGH(HH_PCMTimerISR)       ; 2399 3e 23   
    ldh [hTimerVec+1],a             ; 239b e0 f6   
    ld a,$01                        ; 239d 3e 01     wSfxReq = wMusReq = 1: once the sample is over the driver loads the silent id 1 in both sets
    ld [wSfxReq],a                  ; 239f ea 0f de
    ld [wMusReq],a                  ; 23a2 ea 1f de
    xor a                           ; 23a5 af        APU off, wave RAM = $FF, APU on
    ldh [rNR52],a                   ; 23a6 e0 26   
    ld hl,$ff30                     ; 23a8 21 30 ff
    dec a                           ; 23ab 3d      
    ld c,$10                        ; 23ac 0e 10   
.wave
    ld [hl+],a                      ; 23ae 22      
    dec c                           ; 23af 0d      
    jr nz,HH_PCMStart.wave          ; 23b0 20 fc   
    ld a,$80                        ; 23b2 3e 80   
    ldh [rNR52],a                   ; 23b4 e0 26   
    ldh [rNR11],a                   ; 23b6 e0 11     duty 50 %, CH3 on
    ldh [rNR21],a                   ; 23b8 e0 16   
    ldh [rNR30],a                   ; 23ba e0 1a   
    xor a                           ; 23bc af        NR50 = 0, no sweep, periods 0
    ldh [rNR50],a                   ; 23bd e0 24   
    ldh [rNR10],a                   ; 23bf e0 10   
    ldh [rNR13],a                   ; 23c1 e0 13   
    ldh [rNR23],a                   ; 23c3 e0 18   
    ldh [rNR33],a                   ; 23c5 e0 1d   
    dec a                           ; 23c7 3d        NR51 = $FF, NR12/NR22 = $FF, NR31 = $FF
    ldh [rNR51],a                   ; 23c8 e0 25   
    ldh [rNR12],a                   ; 23ca e0 12   
    ldh [rNR22],a                   ; 23cc e0 17   
    ldh [rNR31],a                   ; 23ce e0 1b   
    ld a,$20                        ; 23d0 3e 20     CH3 level 100 %, NR41 = $20, NR42 = $20
    ldh [rNR32],a                   ; 23d2 e0 1c   
    ldh [rNR41],a                   ; 23d4 e0 20   
    ldh [rNR42],a                   ; 23d6 e0 21   
    ld hl,$ffff                     ; 23d8 21 ff ff  enable the timer interrupt (TMA $C2, 4194304/16/62 = 4228 Hz)
    set 2,[hl]                      ; 23db cb d6   
.wait
    ldh a,[hTimerVec+1]             ; 23dd f0 f6     wait for the end of the sample
    or a                            ; 23df b7      
    jr nz,HH_PCMStart.wait          ; 23e0 20 fb   
    ld a,$77                        ; 23e2 3e 77     NR50 = $77
    ldh [rNR50],a                   ; 23e4 e0 24   
    ret                             ; 23e6 c9      

; HH_PCMTimerISR: reached through the timer vector hTimerVec ($0050).
HH_PCMTimerISR:
    ld hl,$ffff                     ; 23e7 21 ff ff  timer interrupt: one sample
    res 2,[hl]                      ; 23ea cb 96   
    ei                              ; 23ec fb      
    ldh a,[hPCMPtr]                 ; 23ed f0 d6   
    ld l,a                          ; 23ef 6f      
    ldh a,[hPCMPtr+1]               ; 23f0 f0 d7   
    ld h,a                          ; 23f2 67      
    ld a,[hl+]                      ; 23f3 2a      
    cp $ff                          ; 23f4 fe ff   
    jr z,HH_PCMTimerISR.end         ; 23f6 28 1c   
    ldh [rNR50],a                   ; 23f8 e0 24     NR50 = sample
    ld a,$d0                        ; 23fa 3e d0     NR43 = $D0 (slowest noise clock)
    ldh [rNR43],a                   ; 23fc e0 22   
    ld a,$c0                        ; 23fe 3e c0     retrigger all four channels (keeps their outputs at a constant level)
    ldh [rNR14],a                   ; 2400 e0 14   
    ldh [rNR24],a                   ; 2402 e0 19   
    ldh [rNR34],a                   ; 2404 e0 1e   
    ldh [rNR44],a                   ; 2406 e0 23   
    ld a,l                          ; 2408 7d      
    ldh [hPCMPtr],a                 ; 2409 e0 d6   
    ld a,h                          ; 240b 7c      
    ldh [hPCMPtr+1],a               ; 240c e0 d7   
    ld hl,$ffff                     ; 240e 21 ff ff
    set 2,[hl]                      ; 2411 cb d6   
    ret                             ; 2413 c9      
.end
    xor a                           ; 2414 af        end: APU off and on, timer vector 0, NR50 = $77
    ldh [rNR50],a                   ; 2415 e0 24   
    ldh [rNR52],a                   ; 2417 e0 26   
    ldh [hTimerVec+1],a             ; 2419 e0 f6   
    dec a                           ; 241b 3d      
    ldh [rNR52],a                   ; 241c e0 26   
    ld a,$77                        ; 241e 3e 77   
    ldh [rNR50],a                   ; 2420 e0 24   
    ret                             ; 2422 c9      

SECTION "HH PCM decoder", ROM0[$261A]

; HH_PCMDecode: returns the next 3-bit level in a. b = bit buffer, c = bits left, de = stream.
;   1          -> hPCMLast
;   0 v        -> v (v != hPCMLast)
;   0 L v      -> v, hPCMLast = v (L = hPCMLast, v != L)
;   0 L L n4 v -> v, then 11 + n raw 3-bit values
HH_PCMDecode:
    ldh a,[hPCMRun]                 ; 261a f0 90     raw run pending?
    or a                            ; 261c b7      
    jr nz,HH_PCMDecode.raw          ; 261d 20 52   
    dec c                           ; 261f 0d      
    jr nz,HH_PCMDecode.flag         ; 2620 20 05   
    ld a,[de]                       ; 2622 1a        next byte, 8 bits
    inc de                          ; 2623 13      
    ld b,a                          ; 2624 47      
    ld c,$08                        ; 2625 0e 08   
.flag
    rlc b                           ; 2627 cb 00     flag bit 1: repeat hPCMLast
    jr c,HH_PCMDecode.repeat        ; 2629 38 62   
    ld l,$03                        ; 262b 2e 03   
    ld h,$00                        ; 262d 26 00   
.bits3a
    dec c                           ; 262f 0d      
    jr nz,HH_PCMDecode.rl3a         ; 2630 20 05   
    ld a,[de]                       ; 2632 1a      
    inc de                          ; 2633 13      
    ld b,a                          ; 2634 47      
    ld c,$08                        ; 2635 0e 08   
.rl3a
    rlc b                           ; 2637 cb 00   
    rl h                            ; 2639 cb 14   
    dec l                           ; 263b 2d      
    jr nz,HH_PCMDecode.bits3a       ; 263c 20 f1   
    ldh a,[hPCMLast]                ; 263e f0 91     3-bit value different from hPCMLast: output it
    cp h                            ; 2640 bc      
    jr nz,HH_PCMDecode.ret          ; 2641 20 44   
    ld l,$03                        ; 2643 2e 03   
    ld h,$00                        ; 2645 26 00   
.bits3b
    dec c                           ; 2647 0d      
    jr nz,HH_PCMDecode.rl3b         ; 2648 20 05   
    ld a,[de]                       ; 264a 1a      
    inc de                          ; 264b 13      
    ld b,a                          ; 264c 47      
    ld c,$08                        ; 264d 0e 08   
.rl3b
    rlc b                           ; 264f cb 00   
    rl h                            ; 2651 cb 14   
    dec l                           ; 2653 2d      
    jr nz,HH_PCMDecode.bits3b       ; 2654 20 f1   
    ldh a,[hPCMLast]                ; 2656 f0 91     escape + value different: it becomes hPCMLast
    cp h                            ; 2658 bc      
    jr nz,HH_PCMDecode.newLast      ; 2659 20 2e   
    ld l,$04                        ; 265b 2e 04   
    ld h,$00                        ; 265d 26 00   
.bits4
    dec c                           ; 265f 0d      
    jr nz,HH_PCMDecode.rl4          ; 2660 20 05   
    ld a,[de]                       ; 2662 1a      
    inc de                          ; 2663 13      
    ld b,a                          ; 2664 47      
    ld c,$08                        ; 2665 0e 08   
.rl4
    rlc b                           ; 2667 cb 00   
    rl h                            ; 2669 cb 14   
    dec l                           ; 266b 2d      
    jr nz,HH_PCMDecode.bits4        ; 266c 20 f1   
    ld a,$0c                        ; 266e 3e 0c     escape + escape: 4-bit n, a raw run of 12 + n values
    add h                           ; 2670 84      
.raw
    dec a                           ; 2671 3d        count down the run, output a raw 3-bit value
    ldh [hPCMRun],a                 ; 2672 e0 90   
    ld l,$03                        ; 2674 2e 03   
    ld h,$00                        ; 2676 26 00   
.bits3c
    dec c                           ; 2678 0d      
    jr nz,HH_PCMDecode.rl3c         ; 2679 20 05   
    ld a,[de]                       ; 267b 1a      
    inc de                          ; 267c 13      
    ld b,a                          ; 267d 47      
    ld c,$08                        ; 267e 0e 08   
.rl3c
    rlc b                           ; 2680 cb 00   
    rl h                            ; 2682 cb 14   
    dec l                           ; 2684 2d      
    jr nz,HH_PCMDecode.bits3c       ; 2685 20 f1   
.ret
    ld a,h                          ; 2687 7c      
    ret                             ; 2688 c9      
.newLast
    ld a,h                          ; 2689 7c      
    ldh [hPCMLast],a                ; 268a e0 91   
    ret                             ; 268c c9      
.repeat
    ldh a,[hPCMLast]                ; 268d f0 91   
    ret                             ; 268f c9      

SECTION "HH sound driver", ROMX[$4000], BANK[$1]

; Bank 1 starts with a jump to the update and the driver version string.
HH_SndUpdateJP:
    jp HH_SndUpdate                 ; 4000 c3 1f 46
HH_Version:
    db "** Ver 6.04 **"          ; 4003

; HH_ChanOwner: b = channel offset, h = $DE. Returns (b = owning track) only when that
; track read a new row this update and it is not a hold; else returns from the caller.
; HH_MusOwner (a = music track): the same test for the music track alone.
HH_ChanOwner:
    ld h,HIGH(wSfxTracks)           ; 4011 26 de     SFX track b on?
    ld l,b                          ; 4013 68      
    ld a,[hl+]                      ; 4014 2a      
    or a                            ; 4015 b7      
    jr z,HH_ChanOwner.music         ; 4016 28 0e   
    ld a,[hl]                       ; 4018 7e        not on its row: nobody writes
    or a                            ; 4019 b7      
    jr nz,HH_OwnerNone              ; 401a 20 1f   
    ld a,$0a                        ; 401c 3e 0a     TRK_NOTE
    add b                           ; 401e 80      
    ld l,a                          ; 401f 6f      
    ld a,[hl]                       ; 4020 7e      
    cp $89                          ; 4021 fe 89     hold: nobody writes
    jr z,HH_OwnerNone               ; 4023 28 16   
    ret                             ; 4025 c9      
.music
    ld a,b                          ; 4026 78        SFX off: music track
    add $40                         ; 4027 c6 40   
HH_MusOwner:
    ld b,a                          ; 4029 47      
    ld l,a                          ; 402a 6f      
    ld a,[hl+]                      ; 402b 2a      
    or a                            ; 402c b7      
    jr z,HH_OwnerNone               ; 402d 28 0c   
    ld a,[hl]                       ; 402f 7e      
    or a                            ; 4030 b7      
    jr nz,HH_OwnerNone              ; 4031 20 08   
    ld a,$0a                        ; 4033 3e 0a   
    add b                           ; 4035 80      
    ld l,a                          ; 4036 6f      
    ld a,[hl]                       ; 4037 7e      
    cp $89                          ; 4038 fe 89   
    ret nz                          ; 403a c0      
HH_OwnerNone:
    pop de                          ; 403b d1        drop the caller
    ret                             ; 403c c9      

; Channel output, once per row of the owning track. The ownership also decides which set's
; envelope/vibrato blocks run (bit 0 of their flags = suspended).
HH_Ch1Out:
    call HH_ChanOwner               ; 403d cd 11 40
    ld a,b                          ; 4040 78      
    add $07                         ; 4041 c6 07     NR10 = TRK_NR10
    ld l,a                          ; 4043 6f      
