    ld d,$00                        ; 4105 16 00   
    add hl,de                       ; 4107 19      
    ld a,[hl+]                      ; 4108 2a      
    ld d,h                          ; 4109 54      
    ld e,l                          ; 410a 5d      
    pop hl                          ; 410b e1      
