    inc c                           ; 410f 0c      
    ld a,[de]                       ; 4110 1a        period high | TRK_NRX4 | trigger
    or [hl]                         ; 4111 b6      
    or $80                          ; 4112 f6 80   
    ldh [c],a                       ; 4114 e2      
    inc hl                          ; 4115 23      
    ld [hl],a                       ; 4116 77        TRK_LASTNRX4 = NRx4 written
