    push hl                         ; 411d e5      
    ld hl,HH_PeriodTable            ; 411e 21 f2 47
    ld d,$00                        ; 4121 16 00   
    add hl,de                       ; 4123 19      
    ld a,[hl+]                      ; 4124 2a      
    ld d,h                          ; 4125 54      
    ld e,l                          ; 4126 5d      
    pop hl                          ; 4127 e1      
    inc hl                          ; 4128 23      
    ld [hl+],a                      ; 4129 22      
    ld a,[de]                       ; 412a 1a      
    or [hl]                         ; 412b b6      
    or $80                          ; 412c f6 80   
