    ld a,b                          ; 413b 78      
    add $08                         ; 413c c6 08   
    ld l,a                          ; 413e 6f      
    ld c,$1c                        ; 413f 0e 1c   
    ld a,[hl+]                      ; 4141 2a      
    ldh [rNR31],a                   ; 4142 e0 1b   
    ld a,[hl+]                      ; 4144 2a      
    ldh [rNR32],a                   ; 4145 e0 1c   
    ld a,[hl+]                      ; 4147 2a      
