; HH_LoadRequest: hl = request byte, bc = first track of the set (c bit 6 = music).
HH_LoadRequest:
    ld a,[hl]                       ; 41d5 7e        request id
    or a                            ; 41d6 b7      
    ret z                           ; 41d7 c8      
    cp $ff                          ; 41d8 fe ff   
    ret z                           ; 41da c8      
    ld d,$ff                        ; 41db 16 ff     taken
    ld [hl],d                       ; 41dd 72      
    ld l,a                          ; 41de 6f      
    bit 6,c                         ; 41df cb 71     music set?
    jr nz,HH_LoadRequest.table      ; 41e1 20 13   
    xor a                           ; 41e3 af        SFX: clear the frame stamps and free the SFX channels
    ld [wSndFrame],a                ; 41e4 ea 5f de
    ld [wSfxEndFrame],a             ; 41e7 ea 6f de
    ld [wMusTracks+$3F],a           ; 41ea ea 7f de
    ld [$de8f],a                    ; 41ed ea 8f de
    ld [$de9f],a                    ; 41f0 ea 9f de
    call HH_SilenceSfxChans         ; 41f3 cd 43 47
.table
    ld h,$00                        ; 41f6 26 00     HH_SoundTable + id * 8 (16-bit)
    add hl,hl                       ; 41f8 29      
    add hl,hl                       ; 41f9 29      
    add hl,hl                       ; 41fa 29      
    ld de,HH_SoundTable             ; 41fb 11 2b 4a
    add hl,de                       ; 41fe 19      
    ld e,$04                        ; 41ff 1e 04   
.track
    ld a,$01                        ; 4201 3e 01     TRK_SPEED = 1
    ld [bc],a                       ; 4203 02      
    inc c                           ; 4204 0c      
    dec a                           ; 4205 3d        TRK_TICK = 0
    ld [bc],a                       ; 4206 02      
    inc c                           ; 4207 0c      
    ld a,[hl+]                      ; 4208 2a        TRK_PTR
    ld [bc],a                       ; 4209 02      
    inc c                           ; 420a 0c      
    ld a,[hl+]                      ; 420b 2a      
    ld [bc],a                       ; 420c 02      
    inc c                           ; 420d 0c      
    inc c                           ; 420e 0c      
    inc c                           ; 420f 0c      
    xor a                           ; 4210 af        TRK_DEPTH = 0
    ld [bc],a                       ; 4211 02      
    ld a,c                          ; 4212 79      
    add $0a                         ; 4213 c6 0a   
    ld c,a                          ; 4215 4f      
    dec e                           ; 4216 1d      
    jr nz,HH_LoadRequest.track      ; 4217 20 e8   
    ret                             ; 4219 c9      

; HH_NextTrack / HH_TrackStep: tick track wCurTrack, read a row when TRK_TICK reaches TRK_SPEED.
HH_NextTrack:
    ld a,[wCurTrack]                ; 421a fa 90 de  next track
    add $10                         ; 421d c6 10   
HH_TrackStep:
    ld [wCurTrack],a                ; 421f ea 90 de
    ld l,a                          ; 4222 6f      
    ld h,HIGH(wSfxTracks)           ; 4223 26 de   
    ld a,[hl+]                      ; 4225 2a      
    or a                            ; 4226 b7      
    ret z                           ; 4227 c8        off
    inc [hl]                        ; 4228 34        TRK_TICK += 1
    ld d,[hl]                       ; 4229 56      
    cp d                            ; 422a ba        == TRK_SPEED?
    ret nz                          ; 422b c0      
    xor a                           ; 422c af        TRK_TICK = 0, read a row
    ld [hl+],a                      ; 422d 22      
    ld c,[hl]                       ; 422e 4e      
    inc l                           ; 422f 2c      
    ld b,[hl]                       ; 4230 46      
HH_ReadByte:
    ld a,[bc]                       ; 4231 0a      
    inc bc                          ; 4232 03      
    cp $80                          ; 4233 fe 80     $00-$7F note
    jr c,HH_StoreNote               ; 4235 38 15   
    cp $91                          ; 4237 fe 91     $91-$FF speed
    jr nc,HH_SetSpeed               ; 4239 30 27   
    sub $80                         ; 423b d6 80     $80-$90 command
    sla a                           ; 423d cb 27   
    ld e,a                          ; 423f 5f      
    ld d,$00                        ; 4240 16 00   
    ld hl,HH_CmdTable               ; 4242 21 6e 42
    add hl,de                       ; 4245 19      
    ld a,[hl+]                      ; 4246 2a      
    ld h,[hl]                       ; 4247 66      
    ld l,a                          ; 4248 6f      
    jp hl                           ; 4249 e9      
HH_Cmd89_Hold:
    ld a,$89                        ; 424a 3e 89   
HH_StoreNote:
    ld e,a                          ; 424c 5f      
    ld a,[wCurTrack]                ; 424d fa 90 de
    add $0a                         ; 4250 c6 0a   
    ld l,a                          ; 4252 6f      
    ld h,HIGH(wSfxTracks)           ; 4253 26 de   
    ld [hl],e                       ; 4255 73      
    ld a,[wCurTrack]                ; 4256 fa 90 de
    add $02                         ; 4259 c6 02   
    ld l,a                          ; 425b 6f      
    ld h,HIGH(wSfxTracks)           ; 425c 26 de   
    ld [hl],c                       ; 425e 71      
    inc l                           ; 425f 2c      
    ld [hl],b                       ; 4260 70      
    ret                             ; 4261 c9      
HH_SetSpeed:
    sub $91                         ; 4262 d6 91     TRK_SPEED = byte - $91
    ld e,a                          ; 4264 5f      
    ld a,[wCurTrack]                ; 4265 fa 90 de
    ld l,a                          ; 4268 6f      
    ld h,HIGH(wSfxTracks)           ; 4269 26 de   
    ld [hl],e                       ; 426b 73      
    jr HH_ReadByte                  ; 426c 18 c3   

; HH_CmdTable: commands $80-$90
HH_CmdTable:
    dw HH_Cmd80_NRx1, HH_Cmd81_NR10, HH_Cmd82_Transpose, HH_Cmd83_NRx2; 426e  $80-$83
    dw HH_Cmd84_NR50, HH_Cmd85_Call, HH_Cmd86_Return, HH_Cmd87_Stop; 4276  $84-$87
    dw HH_Cmd88_NRx4, HH_Cmd89_Hold, HH_Cmd8A_MusPan, HH_Cmd8B_Jump; 427e  $88-$8B
    dw HH_Cmd8C_Wave, HH_Cmd8D_Env, HH_Cmd8E_Vib, HH_Cmd8F_SfxPan; 4286  $8C-$8F
    dw HH_Cmd90_PanMask             ; 428e  $90

; Command handlers. bc = stream pointer after the command byte.
HH_Cmd8F_SfxPan:
