    ld a,e                          ; 42bc 7b      
    and $0f                         ; 42bd e6 0f   
    ld e,a                          ; 42bf 5f      
    ld d,$00                        ; 42c0 16 00   
    ld hl,HH_EnvPresets             ; 42c2 21 0c 4a  preset = HH_EnvPresets[arg & 15]
    add hl,de                       ; 42c5 19      
    ld a,[hl]                       ; 42c6 7e      
    ld e,a                          ; 42c7 5f      
    and $0f                         ; 42c8 e6 0f   
    pop hl                          ; 42ca e1      
    ld [hl+],a                      ; 42cb 22        rate = preset & 15
    xor a                           ; 42cc af        wait = step = 0
    ld [hl+],a                      ; 42cd 22      
    ld [hl+],a                      ; 42ce 22      
    ld a,e                          ; 42cf 7b      
    and $f0                         ; 42d0 e6 f0   
