    ld l,a                          ; 42e7 6f      
    ld h,HIGH(wSfxTracks)           ; 42e8 26 de   
    ld a,[bc]                       ; 42ea 0a      
    inc bc                          ; 42eb 03      
    ld d,a                          ; 42ec 57      
    or a                            ; 42ed b7      
    jr z,HH_Cmd8E_Vib.flags         ; 42ee 28 02   
    ld a,$80                        ; 42f0 3e 80   
.flags
