HH_Cmd85_Call:
    ld a,[wCurTrack]                ; 435d fa 90 de  TRK_DEPTH += 1
    add $06                         ; 4360 c6 06   
    ld l,a                          ; 4362 6f      
    ld h,HIGH(wSfxTracks)           ; 4363 26 de   
    ld a,[hl]                       ; 4365 7e      
    ld d,a                          ; 4366 57      
    inc d                           ; 4367 14      
    ld [hl],d                       ; 4368 72      
    ld d,a                          ; 4369 57      
    ld a,[wCurTrack]                ; 436a fa 90 de  wCallStack + track + 2 * old depth
    sla d                           ; 436d cb 22   
    add d                           ; 436f 82      
    ld l,a                          ; 4370 6f      
    ld h,HIGH(wCallStack)           ; 4371 26 df   
    ld a,[bc]                       ; 4373 0a      
    inc bc                          ; 4374 03      
    ld e,a                          ; 4375 5f      
    ld a,[bc]                       ; 4376 0a      
    inc bc                          ; 4377 03      
    ld [hl],c                       ; 4378 71        push the return address
    inc l                           ; 4379 2c      
    ld [hl],b                       ; 437a 70      
    ld b,a                          ; 437b 47      
    ld c,e                          ; 437c 4b      
    jp HH_ReadByte                  ; 437d c3 31 42
HH_Cmd86_Return:
    ld a,[wCurTrack]                ; 4380 fa 90 de  TRK_DEPTH
    add $06                         ; 4383 c6 06   
    ld l,a                          ; 4385 6f      
    ld h,$de                        ; 4386 26 de   
    ld a,[hl]                       ; 4388 7e      
    or a                            ; 4389 b7      
    jr z,HH_Cmd86_Return.end        ; 438a 28 11   
    dec [hl]                        ; 438c 35        pop
    ld d,[hl]                       ; 438d 56      
    ld a,[wCurTrack]                ; 438e fa 90 de
    sla d                           ; 4391 cb 22   
    add d                           ; 4393 82      
    ld l,a                          ; 4394 6f      
    ld h,HIGH(wCallStack)           ; 4395 26 df   
    ld c,[hl]                       ; 4397 4e      
    inc l                           ; 4398 2c      
    ld b,[hl]                       ; 4399 46      
    jp HH_ReadByte                  ; 439a c3 31 42
.end
    ld a,[wCurSet]                  ; 439d fa 91 de  depth 0: this track ends
    cp $01                          ; 43a0 fe 01   
    jr z,HH_Cmd86_Return.music      ; 43a2 28 2a   
    call HH_TrackCleanup            ; 43a4 cd 9b 46  SFX track: give the channel back to the music
    ld a,[wCurTrack]                ; 43a7 fa 90 de
    ld l,a                          ; 43aa 6f      
    ld h,HIGH(wSfxTracks)           ; 43ab 26 de   
    ld [hl],$00                     ; 43ad 36 00   
    ld a,[wCurTrack]                ; 43af fa 90 de  wSfxEndFrame + track = wSndFrame
    add $6f                         ; 43b2 c6 6f   
    ld l,a                          ; 43b4 6f      
    ld h,HIGH(wSfxTracks)           ; 43b5 26 de   
    ld a,[wSndFrame]                ; 43b7 fa 5f de
    ld [hl],a                       ; 43ba 77      
    ld hl,wSfxTracks                ; 43bb 21 00 de  all SFX tracks off?
    ld a,[hl]                       ; 43be 7e      
    ld l,$10                        ; 43bf 2e 10   
    or [hl]                         ; 43c1 b6      
    ld l,$20                        ; 43c2 2e 20   
    or [hl]                         ; 43c4 b6      
    ld l,$30                        ; 43c5 2e 30   
    or [hl]                         ; 43c7 b6      
    jr nz,HH_Cmd86_Return.sfxDone   ; 43c8 20 03   
    ld [wSfxReq],a                  ; 43ca ea 0f de  wSfxReq = 0
.sfxDone
    ret                             ; 43cd c9      
.music
    call HH_TrackCleanup            ; 43ce cd 9b 46
    ld a,[wCurTrack]                ; 43d1 fa 90 de
    ld l,a                          ; 43d4 6f      
    ld h,$de                        ; 43d5 26 de   
    ld [hl],$00                     ; 43d7 36 00   
    ld hl,wMusTracks                ; 43d9 21 40 de
    ld a,[hl]                       ; 43dc 7e      
    ld l,$50                        ; 43dd 2e 50   
    or [hl]                         ; 43df b6      
    ld l,$60                        ; 43e0 2e 60   
    or [hl]                         ; 43e2 b6      
    ld l,$70                        ; 43e3 2e 70   
    or [hl]                         ; 43e5 b6      
    jr nz,HH_Cmd86_Return.musDone   ; 43e6 20 03   
    ld [wMusReq],a                  ; 43e8 ea 1f de  wMusReq = 0
.musDone
    ret                             ; 43eb c9      
HH_Cmd87_Stop:
    ld a,[wCurTrack]                ; 43ec fa 90 de  TRK_SPEED = 0, no clean-up
    ld l,a                          ; 43ef 6f      
    ld h,HIGH(wSfxTracks)           ; 43f0 26 de   
    xor a                           ; 43f2 af      
    ld [hl],a                       ; 43f3 77      
    ret                             ; 43f4 c9      
HH_Cmd8B_Jump:
    ld a,[bc]                       ; 43f5 0a      
    inc bc                          ; 43f6 03      
    ld l,a                          ; 43f7 6f      
    ld a,[bc]                       ; 43f8 0a      
    inc bc                          ; 43f9 03      
    ld b,a                          ; 43fa 47      
    ld c,l                          ; 43fb 4d      
    jp HH_ReadByte                  ; 43fc c3 31 42

; HH_EnvTick: software volume envelopes. Block (8 bytes): flags, rate, wait, step, table, arg.
; Every rate + 1 updates the step advances (0-7) and NRx2 = HH_EnvTables[table * 8 + step] is written
; with a retrigger (0 = no write). Step 7 stays and is written again every update.
HH_EnvTick:
    ld hl,wEnv                      ; 43ff 21 c0 de  eight envelope blocks of 8 bytes
.block
    bit 7,[hl]                      ; 4402 cb 7e     bit 7: on
    jr nz,HH_EnvTick.on             ; 4404 20 09   
    ld de,$0008                     ; 4406 11 08 00
    add hl,de                       ; 4409 19      
    ld a,l                          ; 440a 7d      
    or a                            ; 440b b7      
    jr nz,HH_EnvTick.block          ; 440c 20 f4   
    ret                             ; 440e c9      
.on
    ld b,[hl]                       ; 440f 46        b = flags, c = rate
    inc hl                          ; 4410 23      
    ld a,[hl+]                      ; 4411 2a      
    ld c,a                          ; 4412 4f      
    ld a,[hl]                       ; 4413 7e        wait counter running?
    or a                            ; 4414 b7      
    jr nz,HH_EnvTick.waiting        ; 4415 20 35   
    inc hl                          ; 4417 23      
    push hl                         ; 4418 e5      
    bit 0,b                         ; 4419 cb 40     bit 0: suspended (the other set owns the channel)
    jr nz,HH_EnvTick.advance        ; 441b 20 1b   
    ld b,h                          ; 441d 44      
    ld c,l                          ; 441e 4d      
    inc hl                          ; 441f 23      
    ld a,[hl]                       ; 4420 7e      
    ld e,a                          ; 4421 5f      
    ld d,$00                        ; 4422 16 00   
    ld hl,HH_EnvIndex               ; 4424 21 1b 4a  HH_EnvIndex[table] = table * 8
    add hl,de                       ; 4427 19      
    ld e,[hl]                       ; 4428 5e      
    ld hl,HH_EnvTables              ; 4429 21 94 49
    add hl,de                       ; 442c 19      
    ld a,[bc]                       ; 442d 0a        + step
    ld e,a                          ; 442e 5f      
    add hl,de                       ; 442f 19      
    ld b,[hl]                       ; 4430 46        NRx2 value, 0 = none
    ld a,b                          ; 4431 78      
    or a                            ; 4432 b7      
    jr z,HH_EnvTick.advance         ; 4433 28 03   
    call HH_EnvApply                ; 4435 cd 53 44
.advance
    pop hl                          ; 4438 e1      
    ld a,[hl]                       ; 4439 7e        step 7 is the last (re-applied every update)
    cp $07                          ; 443a fe 07   
    jr z,HH_EnvTick.nextBlock       ; 443c 28 04   
    inc [hl]                        ; 443e 34        step += 1, wait = 1
    dec hl                          ; 443f 2b      
.countUp
    inc [hl]                        ; 4440 34      
.next
    inc hl                          ; 4441 23      
.nextBlock
    ld de,$0005                     ; 4442 11 05 00
    add hl,de                       ; 4445 19      
    ld a,l                          ; 4446 7d      
    or a                            ; 4447 b7      
    jp nz,HH_EnvTick.block          ; 4448 c2 02 44
    ret                             ; 444b c9      
.waiting
    cp c                            ; 444c b9        wait == rate: back to 0 (next update steps)
    jr nz,HH_EnvTick.countUp        ; 444d 20 f1   
    ld [hl],$00                     ; 444f 36 00   
    jr HH_EnvTick.next              ; 4451 18 ee   

; HH_EnvApply: b = NRx2 value, c = low byte of the block's step field.
HH_EnvApply:
    ld a,c                          ; 4453 79        c = low byte of the step field: block k
    sub $c3                         ; 4454 d6 c3   
    sla a                           ; 4456 cb 27   
    swap a                          ; 4458 cb 37   
    ld c,a                          ; 445a 4f      
    sla a                           ; 445b cb 27   
    ld e,a                          ; 445d 5f      
    ld d,$00                        ; 445e 16 00   
    ld hl,HH_EnvApplyTable          ; 4460 21 6c 44
    add hl,de                       ; 4463 19      
    ld a,[hl+]                      ; 4464 2a      
    ld h,[hl]                       ; 4465 66      
    ld l,a                          ; 4466 6f      
    ld a,c                          ; 4467 79        a = k * 16 = track
    swap a                          ; 4468 cb 37   
    jp hl                           ; 446a e9      
HH_EnvCh3:
    ret                             ; 446b c9      
HH_EnvApplyTable:
    dw HH_EnvCh1, HH_EnvCh2, HH_EnvCh3, HH_EnvCh4; 446c  blocks 0-3 (SFX CH1-CH4)
    dw HH_EnvCh1, HH_EnvCh2, HH_EnvCh3, HH_EnvCh4; 4474  blocks 4-7 (music CH1-CH4)
HH_EnvCh1:
    add $07                         ; 447c c6 07     NR10 = TRK_NR10
    ld l,a                          ; 447e 6f      
    ld h,HIGH(wSfxTracks)           ; 447f 26 de   
    ld c,$10                        ; 4481 0e 10   
    ld a,[hl+]                      ; 4483 2a      
    ldh [c],a                       ; 4484 e2      
    inc c                           ; 4485 0c      
.common
    ld a,[hl+]                      ; 4486 2a        NRx1 = TRK_NRX1
    ldh [c],a                       ; 4487 e2      
    inc c                           ; 4488 0c      
    ld a,b                          ; 4489 78        NRx2 = envelope value
    ldh [c],a                       ; 448a e2      
    inc c                           ; 448b 0c      
    inc hl                          ; 448c 23      
    inc hl                          ; 448d 23      
    inc hl                          ; 448e 23      
    ld a,[hl+]                      ; 448f 2a        NRx3 = TRK_PERLO
    ldh [c],a                       ; 4490 e2      
    inc c                           ; 4491 0c      
    inc hl                          ; 4492 23      
    ld a,[hl]                       ; 4493 7e        NRx4 = TRK_LASTNRX4 (retrigger)
    ldh [c],a                       ; 4494 e2      
    ret                             ; 4495 c9      
HH_EnvCh2:
    ld c,$16                        ; 4496 0e 16   
    add $08                         ; 4498 c6 08   
    ld l,a                          ; 449a 6f      
    ld h,HIGH(wSfxTracks)           ; 449b 26 de   
    jr HH_EnvCh1.common             ; 449d 18 e7   
HH_EnvCh4:
    ld c,$20                        ; 449f 0e 20   
    add $08                         ; 44a1 c6 08   
    ld l,a                          ; 44a3 6f      
    ld h,HIGH(wSfxTracks)           ; 44a4 26 de   
    ld a,[hl+]                      ; 44a6 2a        NR41
    ldh [c],a                       ; 44a7 e2      
    inc c                           ; 44a8 0c      
    ld a,b                          ; 44a9 78        NR42 = envelope value
    ldh [c],a                       ; 44aa e2      
    inc c                           ; 44ab 0c      
    inc hl                          ; 44ac 23      
    ld a,[hl+]                      ; 44ad 2a        NR43 = TRK_NOTE
    ldh [c],a                       ; 44ae e2      
    inc c                           ; 44af 0c      
    inc hl                          ; 44b0 23      
    inc hl                          ; 44b1 23      
    inc hl                          ; 44b2 23      
    ld a,[hl]                       ; 44b3 7e        NR44 = TRK_LASTNRX4
    ldh [c],a                       ; 44b4 e2      
    ret                             ; 44b5 c9      

; HH_VibTick: pitch tables. Block (4 bytes): flags, table, step, unused. Every update
; NRx3 = TRK_PERLO + HH_VibTables[table * 24 + step]; steps 0-11 once, then 12-23 loop.
HH_VibTick:
    ld hl,wVib                      ; 44b6 21 a0 de  seven vibrato blocks of 4 bytes (the last track has none)
.block
    bit 7,[hl]                      ; 44b9 cb 7e   
    jr z,HH_VibTick.skip            ; 44bb 28 2e   
    ld b,[hl]                       ; 44bd 46      
    inc hl                          ; 44be 23      
    ld a,[hl+]                      ; 44bf 2a      
    ld e,a                          ; 44c0 5f      
    push hl                         ; 44c1 e5      
    bit 0,b                         ; 44c2 cb 40   
    jr nz,HH_VibTick.advance        ; 44c4 20 14   
    ld b,h                          ; 44c6 44      
    ld c,l                          ; 44c7 4d      
    ld d,$00                        ; 44c8 16 00     HH_VibIndex[table] = table * 24
    ld hl,HH_VibIndex               ; 44ca 21 8a 49
    add hl,de                       ; 44cd 19      
    ld e,[hl]                       ; 44ce 5e      
    ld hl,HH_VibTables              ; 44cf 21 9a 48
    add hl,de                       ; 44d2 19      
    ld a,[bc]                       ; 44d3 0a        + step
    ld e,a                          ; 44d4 5f      
    add hl,de                       ; 44d5 19      
    ld b,[hl]                       ; 44d6 46        signed delta
    call HH_VibApply                ; 44d7 cd f5 44
.advance
    pop hl                          ; 44da e1      
    ld a,[hl]                       ; 44db 7e        step += 1; 24 -> 12 (steps 12-23 loop)
    inc a                           ; 44dc 3c      
    cp $18                          ; 44dd fe 18   
    jr c,HH_VibTick.store           ; 44df 38 02   
    ld a,$0c                        ; 44e1 3e 0c   
.store
    ld [hl+],a                      ; 44e3 22      
    inc hl                          ; 44e4 23      
    ld a,l                          ; 44e5 7d      
    cp $bc                          ; 44e6 fe bc   
    jr nz,HH_VibTick.block          ; 44e8 20 cf   
    ret                             ; 44ea c9      
.skip
    ld de,$0004                     ; 44eb 11 04 00
    add hl,de                       ; 44ee 19      
    ld a,l                          ; 44ef 7d      
    cp $bc                          ; 44f0 fe bc   
    jr nz,HH_VibTick.block          ; 44f2 20 c5   
    ret                             ; 44f4 c9      
HH_VibApply:
    ld a,c                          ; 44f5 79        k = (c - $A1) / 4
    sub $a1                         ; 44f6 d6 a1   
    srl a                           ; 44f8 cb 3f   
    srl a                           ; 44fa cb 3f   
    ld e,a                          ; 44fc 5f      
    ld hl,HH_VibPerField            ; 44fd 21 0f 46
    add hl,de                       ; 4500 19      
    ld l,[hl]                       ; 4501 6e      
    ld h,HIGH(wSfxTracks)           ; 4502 26 de   
    ld a,[hl]                       ; 4504 7e        TRK_PERLO + delta (no carry into the high bits)
    add b                           ; 4505 80      
    ld hl,HH_VibNRx3                ; 4506 21 17 46
    add hl,de                       ; 4509 19      
    ld l,[hl]                       ; 450a 6e      
    ld h,$ff                        ; 450b 26 ff   
    ld [hl],a                       ; 450d 77        NRx3 (block 3 writes NR33)
    ret                             ; 450e c9      

; HH_WaveTable: 16 CH3 waves, $8C xx copies HH_WaveTable + xx
HH_WaveTable:
    db $00, $11, $22, $33, $44, $55, $66, $77, $88, $99, $aa, $bb, $cc, $dd, $ee, $ff; 450f
    db $00, $11, $23, $46, $9c, $ae, $ee, $ff, $ff, $ee, $dd, $d9, $64, $32, $11, $00; 451f
    db $45, $56, $67, $78, $9a, $ab, $bc, $cd, $45, $56, $67, $78, $9a, $ab, $bc, $cd; 452f
    db $00, $21, $42, $63, $84, $a5, $c6, $e7, $08, $29, $4a, $6b, $8c, $ad, $ce, $ef; 453f
    db $04, $08, $0c, $0f, $0c, $08, $04, $00, $00, $00, $00, $00, $00, $00, $00, $00; 454f
    db $01, $23, $45, $67, $89, $ab, $cd, $ef, $fe, $dc, $ba, $98, $76, $54, $32, $10; 455f
    db $02, $46, $8a, $ce, $ff, $ff, $ff, $ff, $ed, $cb, $a9, $87, $65, $43, $21, $00; 456f
    db $bc, $db, $98, $ac, $ef, $eb, $86, $78, $aa, $94, $21, $35, $78, $53, $45, $8b; 457f
    db $04, $8c, $fc, $87, $8a, $cb, $a9, $ba, $79, $78, $75, $35, $76, $56, $8a, $84; 458f
    db $89, $ac, $de, $ff, $ee, $dc, $ba, $97, $65, $43, $21, $10, $01, $23, $56, $78; 459f
    db $02, $46, $8a, $ce, $ff, $ff, $ff, $ff, $ee, $dd, $cc, $ba, $97, $53, $32, $10; 45af
    db $00, $01, $12, $47, $ac, $be, $ef, $ff, $ee, $ed, $dc, $a8, $53, $21, $11, $00; 45bf
    db $00, $11, $12, $46, $9b, $9e, $ee, $ff, $ff, $ee, $ed, $e9, $64, $21, $11, $00; 45cf
    db $02, $46, $89, $ab, $cd, $ef, $ed, $cb, $a9, $87, $65, $45, $65, $43, $21, $00; 45df
    db $bd, $db, $98, $9c, $ef, $eb, $76, $68, $aa, $94, $21, $24, $88, $53, $35, $8b; 45ef
    db $04, $8c, $fc, $87, $8a, $cb, $a9, $ca, $79, $79, $75, $35, $76, $56, $89, $84; 45ff

; HH_VibPerField / HH_VibNRx3: per vibrato block, the TRK_PERLO field and the NRx3 register
HH_VibPerField:
    db $0c, $1c, $2c, $3c, $4c, $5c, $6c, $7c; 460f
HH_VibNRx3:
    db $13, $18, $1d, $1d, $13, $18, $1d, $1d; 4617

; HH_SndUpdate: once per VBlank (through HH_SndVBlank).
HH_SndUpdate:
    ld hl,wSndFrame                 ; 461f 21 5f de  wSndFrame += 1
    inc [hl]                        ; 4622 34      
    ld hl,wSfxReq                   ; 4623 21 0f de  SFX request
    ld bc,wSfxTracks                ; 4626 01 00 de
    call HH_LoadRequest             ; 4629 cd d5 41
    ld hl,wMusReq                   ; 462c 21 1f de  music request
    ld bc,wMusTracks                ; 462f 01 40 de
    call HH_LoadRequest             ; 4632 cd d5 41
    xor a                           ; 4635 af        wCurSet = 0
    ld [wCurSet],a                  ; 4636 ea 91 de
    call HH_TrackStep               ; 4639 cd 1f 42
    call HH_NextTrack               ; 463c cd 1a 42
    call HH_NextTrack               ; 463f cd 1a 42
    call HH_NextTrack               ; 4642 cd 1a 42
    ld a,$01                        ; 4645 3e 01     wCurSet = 1
    ld [wCurSet],a                  ; 4647 ea 91 de
    call HH_NextTrack               ; 464a cd 1a 42
    call HH_NextTrack               ; 464d cd 1a 42
    call HH_NextTrack               ; 4650 cd 1a 42
    call HH_NextTrack               ; 4653 cd 1a 42
    call HH_UpdatePan               ; 4656 cd 7c 46
    ld b,$00                        ; 4659 06 00   
    call HH_Ch1Out                  ; 465b cd 3d 40
    call HH_Ch1Shadow               ; 465e cd 6d 40
    ld b,$10                        ; 4661 06 10   
    call HH_Ch2Out                  ; 4663 cd 9b 40
    call HH_Ch2Shadow               ; 4666 cd c8 40
    ld b,$20                        ; 4669 06 20   
    call HH_Ch3Out                  ; 466b cd 31 41
    ld b,$30                        ; 466e 06 30   
    call HH_Ch4Out                  ; 4670 cd 82 41
    call HH_Ch4Shadow               ; 4673 cd b1 41
    call HH_EnvTick                 ; 4676 cd ff 43  software envelopes
    jp HH_VibTick                   ; 4679 c3 b6 44  vibratos

; HH_UpdatePan: NR51.
HH_UpdatePan:
    ld hl,wSfxTracks                ; 467c 21 00 de  TRK_SPEED of SFX ch1+ch2+ch3 (add) | ch4 (or)
    ld a,[hl]                       ; 467f 7e      
    ld l,$10                        ; 4680 2e 10   
    add [hl]                        ; 4682 86      
    ld l,$20                        ; 4683 2e 20   
    add [hl]                        ; 4685 86      
    ld l,$30                        ; 4686 2e 30   
    or [hl]                         ; 4688 b6      
    jr z,HH_UpdatePan.write         ; 4689 28 03   
    ld a,[wSfxPan]                  ; 468b fa 3f de  any SFX on: + wSfxPan
.write
    ld c,a                          ; 468e 4f      
    ld a,[wPanMask]                 ; 468f fa 4f de
    ld h,a                          ; 4692 67      
    ld a,[wMusPan]                  ; 4693 fa 2f de  NR51 = (wMusPan & wPanMask) | SFX pan
    and h                           ; 4696 a4      
    or c                            ; 4697 b1      
    ldh [rNR51],a                   ; 4698 e0 25   
    ret                             ; 469a c9      

; HH_TrackCleanup: a track ended with $86 (wCurTrack): reset its blocks, resume the other set's.
HH_TrackCleanup:
    push hl                         ; 469b e5      
    push de                         ; 469c d5      
    call HH_TrackCleanupJump        ; 469d cd a3 46
    pop de                          ; 46a0 d1      
    pop hl                          ; 46a1 e1      
    ret                             ; 46a2 c9      
HH_TrackCleanupJump:
    ld a,[wCurTrack]                ; 46a3 fa 90 de  jump on the track number
    swap a                          ; 46a6 cb 37   
    sla a                           ; 46a8 cb 27   
    ld e,a                          ; 46aa 5f      
    ld d,$00                        ; 46ab 16 00   
    ld hl,HH_CleanupTable           ; 46ad 21 b5 46
    add hl,de                       ; 46b0 19      
    ld a,[hl+]                      ; 46b1 2a      
    ld h,[hl]                       ; 46b2 66      
    ld l,a                          ; 46b3 6f      
    jp hl                           ; 46b4 e9      
HH_CleanupTable:
    dw HH_CleanSfx1, HH_CleanSfx2, HH_CleanSfx3, HH_CleanSfx4; 46b5  SFX CH1-CH4
    dw HH_CleanMus1, HH_CleanMus2, HH_CleanMus3, HH_CleanMus4; 46bd  music CH1-CH4
HH_CleanSfx1:
    ld hl,wVib                      ; 46c5 21 a0 de  SFX CH1 ended: its blocks off
    ld [hl],$01                     ; 46c8 36 01   
    ld l,$c0                        ; 46ca 2e c0   
    ld [hl],$01                     ; 46cc 36 01   
    ld hl,wVib+$10                  ; 46ce 21 b0 de  music CH1 vibrato/envelope resumed
    bit 7,[hl]                      ; 46d1 cb 7e   
    jr z,HH_CleanSfx1.env           ; 46d3 28 02   
    res 0,[hl]                      ; 46d5 cb 86   
.env
    ld hl,wEnv+$20                  ; 46d7 21 e0 de
    bit 7,[hl]                      ; 46da cb 7e   
    ret z                           ; 46dc c8      
    res 0,[hl]                      ; 46dd cb 86   
    ld l,$e2                        ; 46df 2e e2   
    ld [hl],$00                     ; 46e1 36 00   
    ret                             ; 46e3 c9      
HH_CleanSfx2:
    ld hl,wVib+$04                  ; 46e4 21 a4 de
    ld [hl],$01                     ; 46e7 36 01   
    ld l,$c8                        ; 46e9 2e c8   
    ld [hl],$01                     ; 46eb 36 01   
    ld hl,wVib+$14                  ; 46ed 21 b4 de
    bit 7,[hl]                      ; 46f0 cb 7e   
    jr z,HH_CleanSfx2.env           ; 46f2 28 02   
    res 0,[hl]                      ; 46f4 cb 86   
.env
    ld hl,wEnv+$28                  ; 46f6 21 e8 de
    bit 7,[hl]                      ; 46f9 cb 7e   
    ret z                           ; 46fb c8      
    res 0,[hl]                      ; 46fc cb 86   
    ld l,$ea                        ; 46fe 2e ea   
    ld [hl],$00                     ; 4700 36 00   
    ret                             ; 4702 c9      
HH_CleanSfx3:
    ld hl,wVib+$08                  ; 4703 21 a8 de
    ld [hl],$01                     ; 4706 36 01   
