; HH_SilenceSfxChans: before a new SFX loads, every channel the old SFX holds is reset.
HH_SilenceSfxChans:
    push hl                         ; 4743 e5        called when an SFX request is loaded: every channel an SFX still holds
    push de                         ; 4744 d5      
    ld de,wSfxTracks                ; 4745 11 00 de
    ld a,[de]                       ; 4748 1a      
    or a                            ; 4749 b7      
    jr z,HH_SilenceSfxChans.ch2     ; 474a 28 03   
    call HH_SilenceCh1              ; 474c cd 6d 47
.ch2
    ld e,$10                        ; 474f 1e 10   
    ld a,[de]                       ; 4751 1a      
    or a                            ; 4752 b7      
    jr z,HH_SilenceSfxChans.ch3     ; 4753 28 03   
    call HH_SilenceCh2              ; 4755 cd 8c 47
.ch3
    ld e,$20                        ; 4758 1e 20   
    ld a,[de]                       ; 475a 1a      
    or a                            ; 475b b7      
    jr z,HH_SilenceSfxChans.ch4     ; 475c 28 03   
    call HH_SilenceCh3              ; 475e cd a8 47
.ch4
    ld e,$30                        ; 4761 1e 30   
    ld a,[de]                       ; 4763 1a      
    or a                            ; 4764 b7      
    jr z,HH_SilenceSfxChans.done    ; 4765 28 03   
    call HH_SilenceCh4              ; 4767 cd c0 47
.done
    pop de                          ; 476a d1      
    pop hl                          ; 476b e1      
    ret                             ; 476c c9      
HH_SilenceCh1:
    ld hl,wVib+$10                  ; 476d 21 b0 de  music blocks suspended, SFX blocks off
    set 0,[hl]                      ; 4770 cb c6   
    ld l,$e0                        ; 4772 2e e0   
    set 0,[hl]                      ; 4774 cb c6   
    ld hl,wVib                      ; 4776 21 a0 de
    ld [hl],$01                     ; 4779 36 01   
    ld l,$c0                        ; 477b 2e c0   
    ld [hl],$01                     ; 477d 36 01   
    ld l,$07                        ; 477f 2e 07     track fields 7-E
    call HH_ResetTrackRegs          ; 4781 cd de 47
    ld hl,rNR10                     ; 4784 21 10 ff  NR10 = 8, NR11 = $3F, NR12 = 8, NR13 = 0, NR14 = $C0
    ld a,$08                        ; 4787 3e 08   
    ld [hl+],a                      ; 4789 22      
    jr HH_SilenceRegs               ; 478a 18 46   
HH_SilenceCh2:
    ld hl,wVib+$14                  ; 478c 21 b4 de
    set 0,[hl]                      ; 478f cb c6   
    ld l,$e8                        ; 4791 2e e8   
    set 0,[hl]                      ; 4793 cb c6   
    ld hl,wVib+$04                  ; 4795 21 a4 de
    ld [hl],$01                     ; 4798 36 01   
    ld l,$c8                        ; 479a 2e c8   
    ld [hl],$01                     ; 479c 36 01   
    ld l,$17                        ; 479e 2e 17   
    call HH_ResetTrackRegs          ; 47a0 cd de 47
    ld hl,rNR21                     ; 47a3 21 16 ff
    jr HH_SilenceRegs               ; 47a6 18 2a   
HH_SilenceCh3:
    ld hl,wVib+$18                  ; 47a8 21 b8 de
    set 0,[hl]                      ; 47ab cb c6   
    ld hl,wVib+$08                  ; 47ad 21 a8 de
    ld [hl],$01                     ; 47b0 36 01   
    ld l,$28                        ; 47b2 2e 28     TRK_NRX1 = $FF, TRK_NRX2 = 0
    ld a,$ff                        ; 47b4 3e ff   
    ld [hl+],a                      ; 47b6 22      
    inc a                           ; 47b7 3c      
    ld [hl+],a                      ; 47b8 22      
    call HH_ResetTrackRegs.tail     ; 47b9 cd e7 47
    xor a                           ; 47bc af        CH3 DAC off
    ldh [rNR30],a                   ; 47bd e0 1a   
    ret                             ; 47bf c9      
HH_SilenceCh4:
    ld hl,wEnv+$38                  ; 47c0 21 f8 de
    set 0,[hl]                      ; 47c3 cb c6   
    ld hl,wEnv+$18                  ; 47c5 21 d8 de
    ld [hl],$01                     ; 47c8 36 01   
    ld l,$37                        ; 47ca 2e 37   
    call HH_ResetTrackRegs          ; 47cc cd de 47
    ld hl,rNR41                     ; 47cf 21 20 ff
HH_SilenceRegs:
    ld a,$3f                        ; 47d2 3e 3f   
    ld [hl+],a                      ; 47d4 22      
    ld a,$08                        ; 47d5 3e 08   
    ld [hl+],a                      ; 47d7 22      
    xor a                           ; 47d8 af      
    ld [hl+],a                      ; 47d9 22      
    ld a,$c0                        ; 47da 3e c0   
    ld [hl],a                       ; 47dc 77      
    ret                             ; 47dd c9      
HH_ResetTrackRegs:
    ld a,$08                        ; 47de 3e 08   
    ld [hl+],a                      ; 47e0 22      
    ld a,$3f                        ; 47e1 3e 3f   
    ld [hl+],a                      ; 47e3 22      
    ld a,$08                        ; 47e4 3e 08   
    ld [hl+],a                      ; 47e6 22      
.tail
    xor a                           ; 47e7 af      
    ld [hl+],a                      ; 47e8 22      
    ld [hl+],a                      ; 47e9 22      
    ld [hl+],a                      ; 47ea 22      
    ld a,$40                        ; 47eb 3e 40   
    ld [hl+],a                      ; 47ed 22      
    ld a,$c0                        ; 47ee 3e c0   
    ld [hl],a                       ; 47f0 77      
    ret                             ; 47f1 c9      

